import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:path/path.dart' as p;
import 'package:qchat/features/miniapps_host/miniapp_installer.dart';
import 'package:qchat/features/miniapps_host/miniapp_package.dart';

/// The fixtures are generated by
/// `pnpm --filter @qchat/miniapp-compiler fixture:miniapp`.
Uint8List fixture(String version) =>
    File('test/fixtures/miniapp/fixture-$version.qxpkg').readAsBytesSync();

Map<String, String> trustedKeys() {
  final key = jsonDecode(
    File('test/fixtures/miniapp/fixture-key.json').readAsStringSync(),
  ) as Map<String, Object?>;
  return <String, String>{
    key['keyId']! as String: key['publicKeyBase64']! as String,
  };
}

/// One temporary install root per test; the callback mirrors the layout the
/// Android host derives from its own `filesDir`.
class FixtureInstaller {
  FixtureInstaller._(this.root, this.installer);

  static Future<FixtureInstaller> create() async {
    final root = await Directory.systemTemp.createTemp('qchat-miniapp-test-');
    final installer = MiniAppInstaller(
      runtimeVersion: '1.0.0',
      trustedKeys: trustedKeys(),
      versionDir: (appId, version) async =>
          p.join(root.path, 'apps', appId, version),
    );
    return FixtureInstaller._(root, installer);
  }

  final Directory root;
  final MiniAppInstaller installer;

  Directory versionDir(String appId, String version) =>
      Directory(p.join(root.path, 'apps', appId, version));

  Future<void> dispose() async {
    if (await root.exists()) await root.delete(recursive: true);
  }
}

Future<String> errorCode(Future<Object?> future) async {
  try {
    await future;
  } on MiniAppPackageError catch (error) {
    return error.code;
  }
  fail('expected MiniAppPackageError');
}

void main() {
  late FixtureInstaller fixtureInstaller;

  setUp(() async {
    fixtureInstaller = await FixtureInstaller.create();
  });

  tearDown(() async {
    await fixtureInstaller.dispose();
  });

  test('installs the verified files and the install marker', () async {
    final result = await fixtureInstaller.installer.install(fixture('1.0.0'));

    expect(result.installed, isTrue);
    expect(result.appId, 'qchat.fixture');
    expect(result.version, '1.0.0');

    final dir = fixtureInstaller.versionDir('qchat.fixture', '1.0.0');
    expect(await dir.exists(), isTrue);
    expect(
      await File(p.join(dir.path, 'pages', 'index', 'index.js')).exists(),
      isTrue,
    );
    expect(await File(p.join(dir.path, 'build', 'view.json')).exists(), isTrue);

    final marker =
        jsonDecode(
              await File(p.join(dir.path, 'install.json')).readAsString(),
            )
            as Map<String, Object?>;
    expect(marker['format'], 'qchat-miniapp-install');
    expect(marker['formatVersion'], 1);
    expect(marker['appId'], 'qchat.fixture');
    expect(marker['version'], '1.0.0');
    expect(marker['keyId'], 'fixture-test-key');
    expect((marker['fingerprint']! as String).length, 64);
  });

  test('installing the same package twice writes nothing the second time', () async {
    final first = await fixtureInstaller.installer.install(fixture('1.0.0'));
    final second = await fixtureInstaller.installer.install(fixture('1.0.0'));

    expect(first.installed, isTrue);
    expect(second.installed, isFalse);
    expect(second.versionDir, first.versionDir);
  });

  test('a different package for an installed version is refused', () async {
    await fixtureInstaller.installer.install(fixture('1.0.0'));
    // `fixture-1.0.0-alt` is a second valid package for the same version with
    // different content; overwriting the installed one would change the bytes
    // under a session that is already running.
    expect(
      await errorCode(fixtureInstaller.installer.install(fixture('1.0.0-alt'))),
      'PACKAGE_INSTALL_FAILED',
    );
  });

  test('a downgrade is refused unless the caller allows it', () async {
    await fixtureInstaller.installer.install(fixture('1.1.0'));

    expect(
      await errorCode(fixtureInstaller.installer.install(fixture('1.0.0'))),
      'PACKAGE_DOWNGRADE_BLOCKED',
    );
    expect(
      await fixtureInstaller.installer.installedVersions(
        'qchat.fixture',
        '1.1.0',
      ),
      ['1.1.0'],
    );

    final allowed = await fixtureInstaller.installer.install(
      fixture('1.0.0'),
      allowDowngrade: true,
    );
    expect(allowed.installed, isTrue);
    expect(
      await fixtureInstaller.installer.installedVersions(
        'qchat.fixture',
        '1.0.0',
      ),
      ['1.1.0', '1.0.0'],
    );
  });

  test('only the newest two versions are kept', () async {
    await fixtureInstaller.installer.install(fixture('1.0.0'));
    await fixtureInstaller.installer.install(fixture('1.1.0'));
    await fixtureInstaller.installer.install(fixture('1.2.0'));

    expect(
      await fixtureInstaller.installer.installedVersions(
        'qchat.fixture',
        '1.2.0',
      ),
      ['1.2.0', '1.1.0'],
    );
    expect(
      await fixtureInstaller.versionDir('qchat.fixture', '1.0.0').exists(),
      isFalse,
    );
  });

  test('a failed verification leaves no directory behind', () async {
    final installer = MiniAppInstaller(
      runtimeVersion: '1.0.0',
      trustedKeys: const <String, String>{},
      versionDir: (appId, version) async =>
          p.join(fixtureInstaller.root.path, 'apps', appId, version),
    );

    expect(
      await errorCode(installer.install(fixture('1.0.0'))),
      'PACKAGE_SIGNATURE_INVALID',
    );
    expect(
      await Directory(
        p.join(fixtureInstaller.root.path, 'apps'),
      ).exists(),
      isFalse,
    );
  });

  test('a stale staging directory is removed and never listed', () async {
    final versionsDir = fixtureInstaller
        .versionDir('qchat.fixture', '1.0.0')
        .parent;
    await Directory(
      p.join(versionsDir.path, '0.9.0.staging'),
    ).create(recursive: true);

    await fixtureInstaller.installer.install(fixture('1.0.0'));

    expect(
      await Directory(p.join(versionsDir.path, '0.9.0.staging')).exists(),
      isFalse,
    );
    expect(
      await fixtureInstaller.installer.installedVersions(
        'qchat.fixture',
        '1.0.0',
      ),
      ['1.0.0'],
    );
  });

  test('isInstalled is true only for a verified install', () async {
    expect(
      await fixtureInstaller.installer.isInstalled('qchat.fixture', '1.0.0'),
      isFalse,
    );
    await fixtureInstaller.installer.install(fixture('1.0.0'));
    expect(
      await fixtureInstaller.installer.isInstalled('qchat.fixture', '1.0.0'),
      isTrue,
    );
    expect(
      await fixtureInstaller.installer.isInstalled('qchat.fixture', '9.9.9'),
      isFalse,
    );
  });
}
